def parse_handler_block_ids(text: str) -> List[str]:
    value = _assigned_literal(text, "BLOCK_IDS")
    if not isinstance(value, (list, tuple)):
        return []
    return [str(item) for item in value if str(item).strip()]


def parse_handler_default_actions(text: str) -> Dict[str, str]:
    value = _assigned_literal(text, "BLOCK_DEFAULT_ACTIONS")
    if not isinstance(value, dict):
        return {}
    return {
        str(key): str(val)
        for key, val in value.items()
        if str(key).strip() and isinstance(val, str) and val.strip()
    }


def apply_default_actions_to_handler(
    text: str, default_actions: Mapping[str, str]
) -> str:
    """Rewrite ``BLOCK_DEFAULT_ACTIONS = …`` so keep-path source is honest.

    The assignment is located on the syntax tree and replaced by its line
    span; absent, it goes right after ``BLOCK_IDS = …``; with neither (or
    source that does not parse), it leads the module.
    """
    blob = text or ""
    assignment = f"BLOCK_DEFAULT_ACTIONS = {dict(default_actions or {})!r}"
    tree = _tree(blob)
    if tree is None:
        return assignment + "\n" + blob
    lines = blob.splitlines(keepends=True)
    existing = _assignment(tree, "BLOCK_DEFAULT_ACTIONS")
    if existing is not None:
        start, end = existing.lineno - 1, existing.end_lineno
        indent = lines[start][: existing.col_offset]
        newline = "\n" if lines[end - 1].endswith("\n") else ""
        return "".join(lines[:start] + [indent + assignment + newline] + lines[end:])
    ids = _assignment(tree, "BLOCK_IDS")
    if ids is not None:
        end = ids.end_lineno
        head = "".join(lines[:end])
        if not head.endswith("\n"):
            head += "\n"
        return head + assignment + "\n" + "".join(lines[end:])
    return assignment + "\n" + blob


def block_takes_action(block_id: str) -> Optional[bool]:
    """Does this Store block dispatch on an action at all?

    True when its block.json declares an ``action``/``operation`` input or its
    code reads one; False when its code was found and reads neither; None when
    no code was found (unknown -- the caller fails closed).
    """
    for cand in _harvest_candidate_ids(block_id):
        meta = load_local_block_json(cand)
        if isinstance(meta, Mapping) and any(
            isinstance(i, Mapping) and i.get("name") in _ACTION_INPUT_NAMES
            for i in meta.get("inputs") or ()
        ):
            return True
        found_code = False
        for path in local_block_json_candidates(cand):
            for code in (
                path.with_name("block.py"),
                path.parents[2] / "app" / "blocks" / f"{cand}.py",
            ):
                text = _read_text(code)
                tree = _tree(text) if text else None
                if tree is None:
                    continue
                found_code = True
                if any(
                    isinstance(n, ast.Constant) and n.value in _ACTION_INPUT_NAMES
                    for n in ast.walk(tree)
                ):
                    return True
        if found_code:
            return False
    return None


def reuse_accept_handler_errors(
    text: str,
    block_ids: Optional[Sequence[str]] = None,
    *,
    capability_id: str = "",
) -> List[str]:
    """Empty = this handler can keyword-dispatch its bound blocks."""
    bids = [
        str(b).strip()
        for b in (block_ids if block_ids is not None else parse_handler_block_ids(text))
        if str(b).strip()
    ]
    if not bids:
        return []
    defaults = parse_handler_default_actions(text)
    errors: List[str] = []
    prefix = f"{capability_id}: " if capability_id else ""
    for bid in bids:
        action = default_block_action(bid, defaults)
        if action:
            continue
        if block_takes_action(bid) is False:
            continue
        errors.append(
            f"{prefix}{bid}: {REUSE_ACCEPT_MISS} — no BLOCK_DEFAULT_ACTIONS "
            f"entry ({PRODUCT_UNKNOWN_ACTION_NONE_HALT})"
        )
    if _passes_action_none(text):
        errors.append(
            f"{prefix}execute() passes action=None "
            f"({PRODUCT_UNKNOWN_ACTION_NONE_HALT})"
        )
    return errors

"""Shared block-call runner for the capability handlers.

This module owns the two contracts every handler keeps and nothing else --
each handler builds its own inputs and makes its own domain decision:

* ``action=`` travels as a KEYWORD, from the handler's own
  ``BLOCK_DEFAULT_ACTIONS`` (the value read from each bound block's own
  contract), never inside the payload dict; ``prepare_block_input`` has
  already shaped the record into what the block accepts;
* every id in the handler's ``BLOCK_IDS`` is called, and a block refusal is
  returned as the capability's refusal -- ``ok: False`` with the refusing
  block named, and nothing persisted -- never reported as success (F1).

A block that raises is also a refusal: the block's own answer is the
diagnosis, so it is recorded in the same shape rather than escaping as a
500.
"""

from __future__ import annotations

from typing import Any, Dict, Iterable, List, Sequence, Tuple

#: A block answer with one of these statuses (or ``ok: False``) did not
#: succeed. "partial" is the word the workflow block uses for a pipeline
#: whose step failed, so reading only "error" would report a failed run as a
#: success.
FAILED_STATUSES = ("error", "failed", "partial")


def is_refusal(envelope: Any) -> bool:
    if not isinstance(envelope, dict):
        return False
    if envelope.get("ok") is False:
        return True
    if str(envelope.get("status") or "").lower() in FAILED_STATUSES:
        return True
    steps = envelope.get("results")
    if isinstance(steps, list):
        for step in steps:
            if isinstance(step, dict) and str(step.get("status") or "").lower() in FAILED_STATUSES:
                return True
    return False


def refusal_text(block_id: str, envelope: Any) -> str:
    if isinstance(envelope, dict):
        detail = envelope.get("error") or envelope.get("message")
        if not detail:
            failed = [
                step for step in (envelope.get("results") or [])
                if isinstance(step, dict)
                and str(step.get("status") or "").lower() in FAILED_STATUSES
            ]
            if failed:
                detail = "; ".join(
                    "%s (%s): %s" % (
                        step.get("step_id") or "step",
                        step.get("block") or "?",
                        str(step.get("error") or step.get("status"))[:160],
                    )
                    for step in failed
                )
    else:
        detail = envelope
    return "%s: %s" % (block_id, str(detail or "refused")[:240])


def call_blocks(
    block_ids: Sequence[str],
    default_actions: Dict[str, Any],
    inputs: Dict[str, Dict[str, Any]],
    *,
    entity: str | None = None,
    roster: Iterable[str] | None = None,
) -> Tuple[Dict[str, Any], List[str]]:
    """Call every declared block once; return (answers, refusals).

    ``inputs`` holds one already-built record per block id. The record is
    passed through ``app.block_inputs.prepare_block_input`` so a field the
    block reads at its top level and a value that must be constructed from
    the record (a channel, a table name, a widget list) are settled here
    rather than demanded of the caller.
    """
    from app.block_inputs import prepare_block_input
    from app.dispatch import execute

    answers: Dict[str, Any] = {}
    peer_ids = list(roster or block_ids)
    for block_id in block_ids:
        action = default_actions.get(block_id)
        data = dict(inputs.get(block_id) or {})
        try:
            data = prepare_block_input(
                block_id, data, action=action, roster=peer_ids,
                entity=entity, default_actions=default_actions,
            )
        except Exception:  # a shaper that cannot apply leaves the record alone
            pass
        try:
            answers[block_id] = execute(block_id, data, action=action)
        except Exception as exc:  # a block refusal is an answer, not a 500
            answers[block_id] = {
                "status": "error",
                "ok": False,
                "block": block_id,
                "error": "%s: %s" % (type(exc).__name__, exc),
            }
    refusals = [
        refusal_text(block_id, envelope)
        for block_id, envelope in answers.items()
        if is_refusal(envelope)
    ]
    return answers, refusals

