def gate_ui_end_to_end(ctx: "GateContext") -> "GateResult":
    """The served UI reaches the platform, and the pilot serves one UI."""
    from app.factory.build.gates import GateResult

    if not (ctx.workspace / "app" / "main.py").is_file():
        return GateResult(
            ok=True,
            gate=GATE_NAME,
            detail="no app to serve a UI from — nothing claimed, nothing owed",
        )

    proc = ctx.run([sys.executable, "-c", _render_probe()])
    line = [
        ln for ln in (proc.stdout or "").splitlines() if ln.startswith("UI_PROBE=")
    ]
    if not line:
        return GateResult(
            ok=False,
            gate=GATE_NAME,
            reason=UI_NOT_WIRED,
            detail=(
                "the UI probe did not report: the product did not boot far "
                "enough to serve its own console"
            ),
            findings=[(proc.stderr or "").strip().splitlines()[-1][:200]] if proc.stderr else [],
        )

    import json as _json

    payload = _json.loads(line[-1].split("=", 1)[1])
    findings: List[str] = list(payload.get("findings") or [])
    # Real, reported, and not yet fatal: the unbuilt frontend needs a node
    # stage in the emitted Dockerfile, and the authority label needs the
    # routes to carry one. Both are owed; neither is the writer's to fix in
    # one pass, and failing on them today would stop every build.
    advisory: List[str] = list(payload.get("advisory") or [])
    if findings:
        return GateResult(
            ok=False,
            gate=GATE_NAME,
            reason=UI_NOT_WIRED,
            detail=findings[0],
            findings=findings + advisory,
            payload={"answered": payload.get("answered") or [], "advisory": advisory},
        )
    return GateResult(
        ok=True,
        gate=GATE_NAME,
        detail=(
            "the served UI drives %d capability(ies) and every route it calls answers"
            % len(payload.get("ui_caps") or [])

"""Deterministic formulas this platform decides with.

Every value here is a calculation, not a customer-owned number: the rates,
thresholds and limits an operator owns live in the environment and are read
at the point of use (see README.md). Money is never computed here from a
typed-in currency or tax rate -- ``money_summary`` reads app.money_settings
and answers WITHHELD while no currency is declared.

Scope READS: caller arguments, app.money_settings, the environment settings
named in README.md. Scope WRITES: caller output only. Scope NEVER: no
network, no block call, no persistence.
"""

from __future__ import annotations

import os
from typing import Any, Dict


def _setting(name: str, default: float) -> float:
    raw = (os.environ.get(name) or "").strip()
    if not raw:
        return default
    try:
        return float(raw)
    except ValueError:
        return default


def brix_drop_per_day(previous_brix: float, brix: float, days: int) -> float:
    """Sugar consumed per day between two readings, never negative."""
    span = max(1, int(days or 1))
    return round(max(0.0, (float(previous_brix) - float(brix))) / span, 4)


def tank_temperature_limit() -> float:
    """The temperature above which a fermentation runs too warm."""
    return _setting("TANK_TEMP_MAX_C", 32.0)


def days_to_target(target_brix: float, brix: float, sugar_per_day: float) -> float | None:
    """Days until the block reaches its target sugar, None when it is not moving."""
    gap = float(target_brix) - float(brix)
    if gap <= 0:
        return 0.0
    if sugar_per_day <= 0:
        return None
    return round(gap / sugar_per_day, 2)


def pick_decision(
    brix: float, target_brix: float, sugar_per_day: float, weather_risk: str,
) -> Dict[str, Any]:
    """The pick-date decision for one block, from sugar and forecast risk.

    Rules (all thresholds are operator settings):
      * target reached            -> pick_now
      * sugar rising and <= 3 days -> pick_now when the forecast is risky,
                                     else schedule_pick
      * sugar rising and <= the scheduling horizon -> schedule_pick
      * sugar flat or falling, risky forecast -> hold
      * otherwise                 -> sample_again
    """
    horizon = _setting("HARVEST_SCHEDULE_HORIZON_DAYS", 10.0)
    immediate = _setting("HARVEST_IMMEDIATE_WINDOW_DAYS", 3.0)
    risk = str(weather_risk or "low").lower()
    remaining = days_to_target(target_brix, brix, sugar_per_day)
    if remaining == 0.0:
        decision = "pick_now"
    elif remaining is None:
        decision = "hold" if risk == "high" else "sample_again"
    elif remaining <= immediate:
        decision = "pick_now" if risk == "high" else "schedule_pick"
    elif remaining <= horizon:
        decision = "hold" if risk == "high" else "schedule_pick"
    else:
        decision = "sample_again"
    return {
        "decision": decision,
        "days_to_target": remaining,
        "weather_risk": risk,
        "sugar_per_day": round(float(sugar_per_day), 4),
        "horizon_days": horizon,
    }


def barrel_fill(
    fill_level_pct: Any, volume_liters: Any, capacity_liters: Any,
) -> Dict[str, Any]:
    """The barrel's fill, from whatever the caller supplied.

    A declared fill level is used as given; otherwise it is computed from
    volume over capacity. A barrel below the topping threshold needs topping.
    """
    threshold = _setting("BARREL_TOPPING_THRESHOLD_PCT", 98.0)
    capacity = float(capacity_liters or 0.0)
    volume = float(volume_liters or 0.0)
    declared = fill_level_pct
    if declared in (None, "") and capacity > 0:
        declared = round(min(100.0, max(0.0, volume / capacity * 100.0)), 2)
    level = round(float(declared or 0.0), 2)
    return {
        "fill_level_pct": level,
        "capacity_liters": round(capacity, 1),
        "volume_liters": round(volume, 1),
        "deficit_liters": round(max(0.0, capacity - volume), 1) if capacity else 0.0,
        "topping_threshold_pct": threshold,
        "topping_due": level < threshold,
    }


def barrel_grid_position(
    cellar: str, row_position: Any,
) -> Dict[str, float]:
    """A within-cellar grid position for a barrel.

    The winery's absolute origin is the operator's setting (WINERY_LATITUDE /
    WINERY_LONGITUDE); without one the origin is 0,0 and the answer is the
    relative cellar grid, which is what the barrel's own location actually
    is. Cellar A and cellar B are offset from the origin by their own
    constant spans, so the same barrel code always answers the same point.
    """
    origin_lat = _setting("WINERY_LATITUDE", 0.0)
    origin_lng = _setting("WINERY_LONGITUDE", 0.0)
    span = _setting("CELLAR_ROW_SPAN_DEG", 0.0001)
    cellar_index = 0 if str(cellar).endswith("a") else 1
    row = 0
    for chunk in str(row_position or "").split():
        digits = "".join(ch for ch in chunk if ch.isdigit())
        if digits:
            row = int(digits)
            break
    return {
        "lat": round(origin_lat + span * (cellar_index * 100 + row), 6),
        "lng": round(origin_lng + span * (row + 1), 6),
        "row_index": float(row),
    }


def allocation_for_tier(tier: str) -> int:
    """Bottles a membership tier is allocated, from the operator's settings."""
    key = "CLUB_ALLOCATION_" + "".join(
        ch.upper() if ch.isalnum() else "_" for ch in str(tier or "")
    ).strip("_")
    return int(_setting(key, _setting("CLUB_ALLOCATION_DEFAULT", 6.0)))


def money_summary() -> Dict[str, Any]:
    """Currency and tax for a money path, read from app.money_settings.

    While no currency is declared the money leg is WITHHELD: no code and no
    rate is invented, and the caller is told which setting to set.
    """
    from app import money_settings

    try:
        currency = money_settings.currency()
    except money_settings.MoneySettingMissing as exc:
        return {
            "currency": None,
            "withheld": True,
            "reason": str(exc),
            "settings": ["PLATFORM_CURRENCY", "PLATFORM_COUNTRY", "PLATFORM_TAX_RATE"],
        }
    summary: Dict[str, Any] = {
        "currency": currency,
        "withheld": False,
        "country": None,
        "tax_rate": None,
    }
    try:
        summary["country"] = money_settings.country()
    except money_settings.MoneySettingMissing:
        summary["country"] = None
    try:
        summary["tax_rate"] = money_settings.tax_rate()
    except money_settings.MoneySettingMissing:
        summary["tax_rate"] = None
    return summary


def scale_amount(amount: float, factor: float) -> Dict[str, Any]:
    """An amount and the factor applied to it, kept apart on purpose.

    The amount is never rewritten with a guessed rate: the factor comes from
    app.money_settings at the point of use, and when the summary is withheld
    the amount is returned unscaled with the reason.
    """
    summary = money_summary()
    base = round(float(amount or 0.0), 2)
    if summary["withheld"]:
        return {
            "amount": base,
            "scaled_amount": base,
            "factor": None,
            "withheld": True,
            "reason": summary.get("reason"),
        }
    return {
        "amount": base,
        "scaled_amount": round(base * float(factor), 2),
        "factor": float(factor),
        "withheld": False,
    }


def counts_summary(rows: Any) -> Dict[str, int]:
    """How many open / in-progress / closed records a list carries."""
    out = {"open": 0, "in_progress": 0, "closed": 0}
    for row in rows if isinstance(rows, list) else []:
        status = str((row or {}).get("status") or "open") if isinstance(row, dict) else "open"
        if status in out:
            out[status] += 1
    return out

